const PET_NAME = env.get('PET_NAME');
const MEAL_WINDOWS = JSON.parse(env.get('MEAL_WINDOWS'));
const CATCHUP_BUFFER_MIN = Number(env.get('CATCHUP_BUFFER_MIN'));

const pad = n => String(n).padStart(2, '0');
function todayStr(d) { return `${d.getFullYear()}-${pad(d.getMonth() + 1)}-${pad(d.getDate())}`; }
function mealIdFor(windowName, d) { return `${windowName}_${todayStr(d)}`; }
function emitEvent(event, extra) {
    return { payload: Object.assign({ event, pet: PET_NAME, time: new Date().toISOString() }, extra) };
}
function feedMsgFor(windowName) {
    const m = { payload: { deviceId: env.get('FEEDER_DEVICE_ID'), amount: Number(env.get('AMOUNT')) } };
    m.meal = windowName;
    m.topic = PET_NAME;
    return m;
}

// --- Daily cleanup broadcast ---
if (msg.payload === 'prune') {
    const today = todayStr(new Date());
    const staleFed = context.keys().filter(k => k.startsWith('fed_') && !k.endsWith(today));
    staleFed.forEach(k => context.set(k, undefined));

    const pending = context.get('pendingMeal');
    let prunedPending = false;
    if (pending && pending.cutoffTs < Date.now()) {
        context.set('pendingMeal', undefined);
        prunedPending = true;
    }

    node.status({ fill: 'grey', shape: 'ring', text: `pruned ${staleFed.length} fed flag(s)` });
    return [null, emitEvent('pruned', { fedFlags: staleFed.length, pendingCleared: prunedPending })];
}

// --- Scheduled window-open trigger (payload is the window name string) ---
const windowIdx = MEAL_WINDOWS.findIndex(w => w.name === msg.payload);
if (windowIdx !== -1) {
    const window = MEAL_WINDOWS[windowIdx];

    // Manual meal (e.g. dinner) - never dispense automatically, just tell
    // whoever's watching 'Events' that the window opened and whether she's
    // home yet. No pending/dedup state is touched, so an auto window later
    // in the day is unaffected by this one being skipped.
    if (window.auto === false) {
        const home = context.get('lastLocation') === 'inside';
        node.status({ fill: 'yellow', shape: 'ring', text: `${window.name}: manual (${home ? 'home' : 'not home'})` });
        return [null, emitEvent('manual_reminder', { meal: window.name, home })];
    }

    const now = new Date();
    const mealId = mealIdFor(window.name, now);
    const dedupKey = 'fed_' + mealId;

    if (context.get(dedupKey)) {
        return [null, null]; // already handled this meal somehow
    }

    // Next window's start instant, wrapping to tomorrow's first window if
    // this is the day's last one (e.g. dinner -> tomorrow's breakfast) -
    // computed as a real timestamp so the wrap across midnight is automatic.
    const next = MEAL_WINDOWS[(windowIdx + 1) % MEAL_WINDOWS.length];
    const wrapsToTomorrow = windowIdx === MEAL_WINDOWS.length - 1;
    const nextStart = new Date(now);
    if (wrapsToTomorrow) nextStart.setDate(nextStart.getDate() + 1);
    const [nh, nm] = next.start.split(':').map(Number);
    nextStart.setHours(nh, nm, 0, 0);
    const cutoffTs = nextStart.getTime() - CATCHUP_BUFFER_MIN * 60 * 1000;

    const location = context.get('lastLocation');
    if (location === 'inside') {
        context.set(dedupKey, true);
        context.set('pendingMeal', undefined);
        node.status({ fill: 'green', shape: 'dot', text: `${window.name}: home, fed` });
        return [feedMsgFor(window.name), emitEvent('fed', { meal: window.name, trigger: 'scheduled' })];
    }

    // Not home yet - give her until CATCHUP_BUFFER_MIN before the next
    // window to walk in and still get this meal. Overwrites any earlier
    // still-pending meal on purpose - no stacking makeup meals.
    context.set('pendingMeal', { mealId, windowName: window.name, cutoffTs });
    node.status({ fill: 'yellow', shape: 'ring', text: `${window.name}: not home, pending` });
    return [null, emitEvent('pending', { meal: window.name, cutoffAt: new Date(cutoffTs).toISOString() })];
}

// --- Pet location update (payload = {id, name, location, where, since}) ---
if (msg.payload && typeof msg.payload === 'object' && 'location' in msg.payload) {
    if (msg.payload.name !== PET_NAME) {
        return [null, null]; // not this instance's cat
    }

    const prevLocation = context.get('lastLocation');
    context.set('lastLocation', msg.payload.location);
    node.status({ fill: msg.payload.location === 'inside' ? 'green' : 'blue', shape: 'dot', text: msg.payload.location });

    // surepetcare-pets emits the CURRENT location on every poll, not just on
    // change - only a genuine outside -> inside transition is an arrival.
    // Require a confirmed prior 'outside' reading, not just 'not inside':
    // on the very first poll after deploy prevLocation is undefined, and a
    // cat already home at startup shouldn't be treated as a fresh arrival.
    if (prevLocation !== 'outside' || msg.payload.location !== 'inside') {
        return [null, null];
    }

    const pending = context.get('pendingMeal');
    if (!pending) {
        node.status({ fill: 'green', shape: 'dot', text: 'inside, nothing pending' });
        return [null, emitEvent('arrival', { fed: false, reason: 'no meal pending' })];
    }
    if (Date.now() > pending.cutoffTs) {
        context.set('pendingMeal', undefined);
        node.status({ fill: 'red', shape: 'dot', text: `missed ${pending.windowName}` });
        return [null, emitEvent('missed', { meal: pending.windowName })];
    }

    const dedupKey = 'fed_' + pending.mealId;
    if (context.get(dedupKey)) {
        context.set('pendingMeal', undefined);
        return [null, null];
    }

    context.set(dedupKey, true);
    context.set('pendingMeal', undefined);
    node.status({ fill: 'green', shape: 'dot', text: `catch-up ${pending.windowName}` });
    return [feedMsgFor(pending.windowName), emitEvent('fed', { meal: pending.windowName, trigger: 'catch-up' })];
}

return [null, null];
